// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // fund the test contract (this) with 3 ether: 1 for constructor + 2 for lockInGuess
        vm.deal(address(this), 3 ether);
        // call lockInGuess with 1 ether (reference accepts, buggy requires 2 ether and thus reverts)
        bool okFirst;
        try c.lockInGuess{value: 1 ether}(keccak256("guess")) {
            okFirst = true;
        } catch {
            okFirst = false;
        }
        // In reference, this call succeeds; in buggy version, it reverts (requires 2 ether)
        // Now the second call: same address (this) tries lockInGuess again with 1 ether
        // Reference: block != 0 because first call succeeded, so require(guesses[msg.sender].block == 0) fails -> revert -> okSecond = false
        // Buggy: first call reverted, so guesses[msg.sender].block == 0, second call with 1 ether also reverts (requires 2 ether) -> okSecond = false
        // Both revert, but the divergence is observable in okFirst
        // We assert that okFirst is true (reference) / false (buggy)
        assertTrue(okFirst);
    }
}

