    }
    function testRegression_property() public {
        // Fund actor with 1 ether
        address actor = address(0x123);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        // Reference: lockInGuess accepts 1 ether, reverts if msg.value != 1 (bug version requires 2)
        bool ok;
        try c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked("test"))) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: call succeeds, contract balance = 2 ether (1 constructor + 1 lockInGuess)
        // Bug: call reverts, contract balance stays 1 ether
        assertEq(address(c).balance, 2 ether);
    }
}

