pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund Alice with 2 ether (1 ether for constructor deposit, though already done in setUp)
        // Actually constructor already took 1 ether from deployer. We'll use Alice as a new user.
        address alice = address(0xABCD);
        vm.deal(alice, 2 ether);

        // Alice locks in a guess: 1 ether in reference, 2 ether in modified version
        bytes32 guessHash = keccak256(abi.encodePacked(uint(1)));
        vm.prank(alice);
        c.lockInGuess{value: 2 ether}(guessHash);

        // Warp to the next block after the guess block
        uint guessBlock = block.number; // lockInGuess sets block = block.number + 1, so guessBlock is block.number at time of lockInGuess
        // Actually lockInGuess sets guesses[msg.sender].block = block.number + 1, so we need to move past that
        vm.roll(block.number + 2);

        // Now settle - this succeeds in reference (balance >= 2 ether) but reverts in modified version (balance 1 ether instead of 2)
        // Because modified version requires 2 ether to lock, but only 1 ether was sent to constructor; total balance = 2 ether (reference) vs 1 ether (modified)
        // Wait, let's recalc: In setUp, deployer sends 1 ether. In modified version, Alice sends 2 ether, so total balance = 3 ether.
        // Actually the reference lockInGuess requires 1 ether, so total = 2 ether. Modified requires 2 ether, total = 3 ether.
        // The settle requires address(this).balance >= 2 ether. Both have enough. So this is not the divergence.
        // Need to think again: The difference is msg.value in lockInGuess: 1 ether vs 2 ether. But settle still pays 2 ether.
        // So with reference: constructor 1 ether + lockInGuess 1 ether = 2 ether. After settle, balance becomes 0.
        // With modified: constructor 1 ether + lockInGuess 2 ether = 3 ether. After settle, still 1 ether left.
        // The divergence could be that reference succeeds (balance after settle = 0), modified succeeds too (balance = 1).
        // Actually both succeed. I need a scenario where modified fails but reference doesn't.
        // Let's try: if Alice uses lockInGuess with 1 ether in reference, but 2 ether in modified, then reference succeeds, modified reverts at require(msg.value == 2 ether).
        // That would cause a revert in the call itself. The test must catch it.
        // So:
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == true (lockInGuess accepts 1 ether)
        // Modified: ok == false (lockInGuess rejects 1 ether, requires 2 ether)
        assertTrue(ok);
    }
}

