pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether from deployer (constructor), add another 1 ether for settle
        vm.deal(address(0x1), 2 ether);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(block.number))));
        // warp to make block.number > guessed block
        vm.roll(block.number + 3);
        // Now settle; in REFERENCE (block.number+1) it succeeds, in BUG (block.number+2) blockhash is 0 so answer mismatch -> requires 2 ether balance left
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(0x1));
        c.settle();
        uint256 balanceAfter = address(c).balance;
        // REFERENCE: 2 ether transferred -> balance becomes 0; BUG: no transfer -> balance stays 2 ether
        assertEq(balanceAfter, 0 ether);
    }
}

