        // blockhash(2) is zero at block 1, but we will warp to block 3 where blockhash(2) is known
        // For simplicity, we compute the answer after warping: but lockInGuess expects a bytes32 argument
        // Let's just set guess to zero bytes32 expecting that at block 3, blockhash(2) is zero => they match
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // Warp to block 3 ( > block.number+1 = 2 )
        vm.roll(3);
        vm.warp(3);

