// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund an attacker
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);

        // Lock in a guess for the next block's hash
        vm.prank(attacker);
        c.lockInGuess{value: 1 ether}(bytes32(0)); // guess doesn't matter, we want block number to be set

        // Advance one block so settle() can be called
        vm.roll(block.number + 2);

        // Now settle — in the reference, the stored block is block.number+1 so blockhash returns non-zero and guess (0) won't match, so transfer won't happen. But we want to observe that in the reference the call succeeds (does not revert). Try-catch to avoid uncaught revert.
        bool ok;
        vm.prank(attacker);
        try c.settle() { ok = true; } catch { ok = false; }

        // The reference: settle() should succeed (no revert) because block.number > stored block even though guess didn't match. The buggy version: stored block = block.number+2, so block.number == block.number? Actually: after vm.roll(block.number+2), block.number = previous+2. Stored block = block.number+1 (reference) => block.number+2 > stored +1? Need careful.
        // Let's compute: initial block.number after setUp = 1. lockInGuess sets stored block = block.number+1 = 2 (reference) or block.number+2 = 3 (bug). vm.roll(block.number+2) = roll to 3. So in reference: stored=2, current=3 => require(block.number > 2) passes. In bug: stored=3, current=3 => require(block.number > 3) fails => revert. So reference call succeeds, bug reverts.
        assertTrue(ok);
    }
}

