pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: Alice locks in a guess at block 2, then settles at block 3
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);

        // Alice sends 1 ether to lockInGuess
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(2))));

        // Warp to block 3
        vm.warp(3);
        vm.roll(3);

        // Alice settles
        vm.prank(alice);
        c.settle();

        // Reference: balance is 0 (2 ether paid out), Bug: balance still 2 ether because settle didn't pay
        assertEq(address(c).balance, 0 ether);
    }
}

