pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund contract with initial 1 ether from constructor, need 2 ether total to payout
        vm.deal(address(c), 1 ether);
        // User has 1 ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        // Predict the correct answer: blockhash for the target block
        // We'll set block.number = 10 before lockInGuess, then target block = 11 in reference, 12 in bug
        vm.roll(10);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(11))));
        // Advance to block 12
        vm.roll(12);
        // For reference: target block is 11, blockhash(11) is known (we set block 10, so blockhash(11)=0 literally but in real chain it would be non-zero; we just check the settlement result)
        // Actually in Foundry test, blockhash for future blocks is 0, so both would fail. We need step properly:
        // Use a real scenario: after lockInGuess, set block.number to 12, then blockhash(11) will be 0 because in Foundry blockhash for non-historical blocks is 0
        // In reference (target=11), blockhash(11)=0 => answer=keccak256(0) => user's guess matches if they guessed keccak256(0)
        // In bug (target=12), blockhash(12)=0 => answer=keccak256(0), but user's guess was keccak256(0) as well? Actually user guessed keccak256(0) too, so both would match. Let's adjust to make reference win.
        // Case: set blockhash(11) to a specific value via vm.eth what? No, we cannot set blockhash. Use that blockhash(block.number-1) is zero in Foundry for non-historical. So reference always wins because blockhash(11) is zero, guess=keccak256(0) matches, user gets 2 eth. Bug: target=12, blockhash(12) is zero, same result? Actually blockhash(12) on block 12 is 0 too. So both win. Need divergence where reference wins and bug loses.
        // Divergence: if blockhash(11) is non-zero in real chain but Foundry gives 0. Simpler: use block.number+1 vs +2 with blockhash from last block. At block 12, blockhash(11) is keccak256 of something? Let's just use the fact that for reference guess = keccak256(abi.encodePacked(blockhash(11))), for block 12, blockhash(12) = 0, so if user guessed keccak256(0) they win in reference but in bug blockhash(12)=0 so they also win. Hmm.
        // Distinct divergence: suppose the guess doesn't match answer. Then in reference the player loses (no transfer), in bug they also lose. Need case where reference transfers but bug reverts or does not transfer.
        // The only difference: bug checks block.number > target, target=12, block.number=12 => condition false (12>12 false), so settle reverts because require fails. Reference: target=11, block.number=12 > 11 true, so settle proceeds.
        // So we need block.number exactly equal to target+1 in bug? Actually bug target = block.number+2, so if block.number = 10, target = 12. At block 12, require(block.number > guesses[msg.sender].block) => 12 > 12 false => revert. Reference target=11, 12 > 11 true.
        // Perfect! So the concrete scenario: at block 10, lockInGuess. Then at block 12, call settle. Reference succeeds (no revert), bug reverts.
        // So we catch the revert:
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok); // reference passes (ok=true), bug fails (ok=false)
    }
}

