        // But we need the divergence: reference sends 2 ether, bug reverts
        // To make reference succeed, guess must equal blockhash(2), which is unknown at lock time
        // Actually, the divergence: reference uses blockhash(block.number+1) from lock time, bug uses blockhash(block.number)
        // We can only act on observed behavior: after settle, check user balance
        // Let's instead check that the reference's settle does not revert and bug's does
        // But the bug's settle does not revert; it just sets block=0 and answer doesn't match so no transfer
        // Both finish without revert but with different user balance
        // Reference: blockhash(2) vs guess blockhash(1) => no match => no transfer
        // Bug: blockhash(1) vs guess blockhash(1) => match => transfer 2 ether if balance >= 2
        // So reference: user gets 0 back (balance after settle = 0), bug: user gets 2 ether (balance = 2)
        // But the test must pass on reference, fail on bug => assertion that reference holds and bug breaks
        // We can assert that user's ether balance after settle is less than 1 (or equal to initial - 1)
        // Reference: user spent 1 ether, got none back => balance = 0
        // Bug: user spent 1 ether, got 2 back => balance = 1 (initial 1 - 1 + 2 = 2? Actually user had 1, sent 1, got 2 => 2)
        uint initialUserBalance = user.balance;

        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);

        // In reference: no transfer, user balance unchanged from initial (since no ether sent back)
        // In bug: transfer 2 ether, user balance increases by 2 from initial (since initial was 0 after deploy? Actually user had 1 sent to contract, then maybe gets 2 back => net +1)
        // Let's just check address(c).balance after settle
        // Reference: balance = 3 - 0 = 3 (no transfer)
        // Bug: balance = 3 - 2 = 1 (2 ether sent)
        assertEq(address(c).balance, 3 ether);
