        // Contract now has 2 ether, deployer lost 1 ether? Actually constructor took 1 ether from deployer, now we add 1 more = 2 ether
        // Simpler: fund a user with 2 ether, user calls lockInGuess{value:1 ether}
        address user = address(0x123);
        vm.deal(user, 2 ether);
        // Set block.number = 100
        vm.roll(100);
        bytes32 guess = keccak256(abi.encodePacked(blockhash(101))); // We know blockhash(101) will be zeroHash at block 100, but we'll compute correctly
        // For reference: blockhash(block.number+1) = blockhash(101) if block.number=100; but we want guess to match reference's answer
        // At block 100, future blocks are unknown, so we pick a guess that will match only if answer is zeroHash
