        try c.settle() { settled = true; } catch { settled = false; }

        // Assert that settle succeeded (buggy version) or not? 
        // For reference: should revert because balance >= 2 fails => settled = false
        // For buggy: should succeed => settled = true
        // We want assertion that reference holds and buggy fails.
        // So assertTrue(settled == false) will be true for reference, false for buggy.
        assertTrue(settled == false);
    }
}

